(6001, 6001, 'EMPRESA', 'Apple Premium Reseller (iShop)', 'Distribuidor oficial Apple en Cartagena. MacBooks, iPhones, iPads, Apple Watch y accesorios con garantía internacional.', 'https://images.unsplash.com/photo-1611186871348-b1ce696e52c9?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901458839-3', 'Apple Premium Reseller (iShop) S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 43 # 43-80', '98053885020', 'Davivienda', 4.9, 12, 'ELITE', NOW() - INTERVAL '41 days'),
(6002, 6002, 'EMPRESA', 'Samsung Experience Store', 'Showroom oficial Samsung. Smartphones Galaxy S24, pantallas Neo QLED, tabletas Tab S9 y electrodomésticos inteligentes Bespoke.', 'https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901615065-5', 'Samsung Experience Store S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 28 # 23-14', '90496391382', 'Davivienda', 4.8, 8, 'ELITE', NOW() - INTERVAL '6 days'),
(6003, 6003, 'EMPRESA', 'Nike Official Store Cartagena', 'Tienda concepto Nike. Air Jordan, Air Force 1, calzado running Pegasus, indumentaria deportiva y streetwear de alto rendimiento.', 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901145166-5', 'Nike Official Store Cartagena S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 32 # 75-93', '20244369195', 'Davivienda', 4.9, 10, 'ELITE', NOW() - INTERVAL '43 days'),
(6004, 6004, 'EMPRESA', 'Adidas Originals & Performance', 'Zapatillas Ultraboost, Samba OG, Stan Smith, ropa de entrenamiento y colaboraciones exclusivas de la marca de las tres rayas.', 'https://images.unsplash.com/photo-1518002171953-a080ee817e1f?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901723533-6', 'Adidas Originals & Performance S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 59 # 68-22', '3090287585', 'Daviplata', 4.8, 15, 'PRO', NOW() - INTERVAL '20 days'),
(6005, 6005, 'EMPRESA', 'Sony Center Caribe', 'Audífonos líderes WH-1000XM5, barras de sonido Dolby Atmos, cámaras profesionales Alpha y accesorios oficiales PlayStation.', 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901404390-9', 'Sony Center Caribe S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 55 # 10-40', '50311516586', 'Davivienda', 4.9, 25, 'PRO', NOW() - INTERVAL '34 days'),
(6006, 6006, 'EMPRESA', 'Decathlon Sports Cartagena', 'Equipamiento para más de 65 deportes: bicicletas de montaña Rockrider, mancuernas Domyos, running Kalenji y senderismo Quechua.', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901121988-5', 'Decathlon Sports Cartagena S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 5 # 47-81', '98232340187', 'Davivienda', 5.0, 12, 'PRO', NOW() - INTERVAL '23 days'),
(6007, 6007, 'EMPRESA', 'Arturo Calle Menswear', 'Moda masculina ejecutiva y casual. Camisas de lino y algodón pima, trajes de corte italiano, chaquetas y calzado formal.', 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901235445-6', 'Arturo Calle Menswear S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 3 # 50-81', '3069415436', 'Nequi', 4.9, 7, 'PRO', NOW() - INTERVAL '45 days'),
(6008, 6008, 'EMPRESA', 'Studio F High Fashion', 'Tendencias en moda femenina contemporánea: vestidos de gala y coctel, blusas frescas, jeans levanta cola y carteras en cuero.', 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901630041-3', 'Studio F High Fashion S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 20 # 59-32', '24144818249', 'Bancolombia', 4.7, 9, 'PRO', NOW() - INTERVAL '5 days'),
(6009, 6009, 'EMPRESA', 'Sephora Beauty Lounge', 'Cosmética de lujo y perfumería francesa. Fragancias Dior, Chanel, Gucci, paletas Huda Beauty y tratamientos faciales antiedad.', 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901132592-7', 'Sephora Beauty Lounge S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 55 # 76-88', '83036481705', 'Bancolombia', 4.8, 13, 'PRO', NOW() - INTERVAL '39 days'),
(6010, 6010, 'EMPRESA', 'IKEA Home & Living', 'Diseño nórdico para el hogar. Sofás modulares, mesas de centro, estanterías funcionales, iluminación cálida y menaje minimalista.', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901305830-9', 'IKEA Home & Living S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 42 # 36-13', '58989813381', 'Bancolombia', 4.9, 23, 'PRO', NOW() - INTERVAL '39 days'),
(6011, 6011, 'EMPRESA', 'Homecenter Constructor', 'Herramientas eléctricas y manuales Stanley, DeWalt y Bosch. Taladros, sierras, compresores e insumos de remodelación profesional.', 'https://images.unsplash.com/photo-1504148455328-c376907d081c?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901788475-1', 'Homecenter Constructor S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 37 # 74-66', '3043022520', 'Nequi', 4.8, 11, 'PRO', NOW() - INTERVAL '25 days'),
(6012, 6012, 'EMPRESA', 'Dermatológica Skincare', 'Clínica de la piel y dermocosmética especializada. Protectores solares toque seco, hidratantes CeraVe, sérums de ácido hialurónico y retinol.', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=300&auto=format&fit=crop&q=80', 'APROBADO', '901263353-8', 'Dermatológica Skincare S.A.S.', 'Cartagena de Indias', 'Cartagena de Indias, Bolívar - Cra 33 # 48-28', '3080021633', 'Daviplata', 4.9, 21, 'PRO', NOW() - INTERVAL '41 days'),
